1	// Kodely data retention runner. The policy itself lives in lib/retention.ts —
2	// this file only decides what to call and how to print it.
3	//
4	//   node scripts/retention.mjs                     # dry run (default)
5	//   node scripts/retention.mjs --only events       # dry run, one rule
6	//   node scripts/retention.mjs --apply             # actually delete
7	//   node scripts/retention.mjs --only sessions --apply
8	//
9	// --dry-run is the default and needs no flag. Deleting requires typing
10	// --apply, because the failure mode of getting this backwards is unrecoverable
11	// and the failure mode of getting it this way round is a wasted SELECT.
12	//
13	// Env: DATABASE_URL is read from .env via scripts/eval/loader.mjs, the same
14	// parser the eval harness uses — Next.js loads .env for you, a bare node
15	// script does not. Nothing else here is shared with that harness.
16	import { loadEnv, quietNodeWarnings, registerTsResolution } from "./eval/loader.mjs";
17	
18	const argv = process.argv.slice(2);
19	
20	if (argv.includes("--help") || argv.includes("-h")) {
21	  console.log(
22	    [
23	      "Usage: node scripts/retention.mjs [--only <rule>] [--apply]",
24	      "",
25	      "  (no flags)      Dry run. Counts what each rule would remove. Default.",
26	      "  --dry-run       Explicit form of the default. Accepted for clarity.",
27	      "  --only <rule>   Run a single rule by key.",
28	      "  --apply         ACTUALLY DELETE. Required for any mutation.",
29	      "",
30	      "Rule keys are printed in the table below every run.",
31	    ].join("\n"),
32	  );
33	  process.exit(0);
34	}
35	
36	const apply = argv.includes("--apply");
37	const onlyIndex = argv.indexOf("--only");
38	const only = onlyIndex === -1 ? null : argv[onlyIndex + 1];
39	
40	if (onlyIndex !== -1 && (!only || only.startsWith("--"))) {
41	  console.error("--only needs a rule key, e.g. --only events");
42	  process.exit(1);
43	}
44	
45	const unknownFlags = argv.filter(
46	  (arg, i) =>
47	    arg.startsWith("--") &&
48	    !["--apply", "--dry-run", "--only", "--help"].includes(arg) &&
49	    i !== onlyIndex + 1,
50	);
51	if (unknownFlags.length > 0) {
52	  console.error(`Unrecognized: ${unknownFlags.join(", ")}. Run with --help.`);
53	  process.exit(1);
54	}
55	
56	// loadEnv also insists on KODELY_FOUNDATION_DIR, because the eval harness dies
57	// confusingly without it. Retention does not touch the foundation at all, so
58	// that particular complaint is not ours — but the .env values are assigned
59	// before it throws, so we keep them and check the one variable we do need.
60	try {
61	  loadEnv({ quiet: true });
62	} catch (err) {
63	  if (!process.env.DATABASE_URL) throw err;
64	}
65	if (!process.env.DATABASE_URL) {
66	  console.error("DATABASE_URL is not set (looked in .env and the environment).");
67	  process.exit(1);
68	}
69	
70	// Node's type-stripping and typeless-package warnings would otherwise land in
71	// the middle of the table.
72	quietNodeWarnings();
73	registerTsResolution();
74	
75	const { RETENTION_RULES, NEVER_PRUNED, findRule, BATCH_SIZE } = await import("../lib/retention.ts");
76	const { db } = await import("../lib/db.ts");
77	
78	const rules = only ? [findRule(only)].filter(Boolean) : RETENTION_RULES;
79	if (only && rules.length === 0) {
80	  console.error(
81	    `No rule named "${only}". Known rules: ${RETENTION_RULES.map((r) => r.key).join(", ")}`,
82	  );
83	  process.exit(1);
84	}
85	
86	/** Host + database only. The connection string carries a password. */
87	function describeDatabase() {
88	  try {
89	    const url = new URL(process.env.DATABASE_URL);
90	    return `${url.host}${url.pathname}`;
91	  } catch {
92	    return "(unparseable DATABASE_URL)";
93	  }
94	}
95	
96	function formatBytes(bytes) {
97	  if (bytes === null) return "—";
98	  if (bytes < 1024) return `${bytes} B`;
99	  const units = ["kB", "MB", "GB", "TB"];
100	  let value = bytes / 1024;
101	  let unit = 0;
102	  while (value >= 1024 && unit < units.length - 1) {
103	    value /= 1024;
104	    unit++;
105	  }
106	  return `${value < 10 ? value.toFixed(1) : Math.round(value)} ${units[unit]}`;
107	}
108	
109	function printTable(rows, columns) {
110	  const widths = columns.map((col) =>
111	    Math.max(col.header.length, ...rows.map((row) => String(col.value(row)).length)),
112	  );
113	  const line = (cells) =>
114	    cells.map((cell, i) => (columns[i].right ? cell.padStart(widths[i]) : cell.padEnd(widths[i]))).join("  ");
115	
116	  console.log(line(columns.map((c) => c.header)));
117	  console.log(widths.map((w) => "-".repeat(w)).join("  "));
118	  for (const row of rows) console.log(line(columns.map((c) => String(c.value(row)))));
119	}
120	
121	async function main() {
122	  console.log("");
123	  console.log(`Kodely retention · ${apply ? "APPLY (deleting)" : "DRY RUN (nothing is deleted)"}`);
124	  console.log(`Database: ${describeDatabase()}`);
125	  console.log(`Rules:    ${rules.map((r) => r.key).join(", ")}`);
126	  console.log("");
127	
128	  // Always count first, even under --apply. The operator gets the same table
129	  // either way, so an --apply run is self-documenting: what it says it removed
130	  // is measured, not assumed.
131	  const results = [];
132	  for (const rule of rules) {
133	    const counted = await rule.count();
134	    results.push({ rule, counted, purged: null });
135	  }
136	
137	  printTable(results, [
138	    { header: "RULE", value: (r) => r.rule.key },
139	    { header: "TARGET", value: (r) => r.rule.target },
140	    { header: "THRESHOLD", value: (r) => r.rule.threshold },
141	    { header: "ROWS", value: (r) => r.counted.rows, right: true },
142	    { header: "OF", value: (r) => r.counted.total, right: true },
143	    { header: "EST. BYTES", value: (r) => formatBytes(r.counted.bytes), right: true },
144	  ]);
145	
146	  console.log("");
147	  for (const { rule } of results) console.log(`  ${rule.key}: ${rule.rationale}`);
148	
149	  const affected = results.reduce((sum, r) => sum + r.counted.rows, 0);
150	  const reclaimable = results.reduce((sum, r) => sum + (r.counted.bytes ?? 0), 0);
151	
152	  console.log("");
153	  console.log(`Total: ${affected} row(s), about ${formatBytes(reclaimable)} reclaimable.`);
154	
155	  if (!apply) {
156	    console.log("");
157	    console.log("Dry run — nothing was deleted. Re-run with --apply to enforce the policy.");
158	    return;
159	  }
160	
161	  if (affected === 0) {
162	    console.log("");
163	    console.log("Nothing to do.");
164	    return;
165	  }
166	
167	  console.log("");
168	  console.log(`Applying in batches of ${BATCH_SIZE}...`);
169	  for (const result of results) {
170	    if (result.counted.rows === 0) {
171	      console.log(`  ${result.rule.key}: nothing to remove.`);
172	      continue;
173	    }
174	    const purged = await result.rule.purge();
175	    result.purged = purged;
176	    const drift = purged.rows === result.counted.rows ? "" : ` (counted ${result.counted.rows})`;
177	    console.log(
178	      `  ${result.rule.key}: ${purged.rows} row(s) in ${purged.batches} batch(es)${drift}` +
179	        (purged.truncated ? " — STOPPED EARLY, re-run to finish" : ""),
180	    );
181	  }
182	
183	  console.log("");
184	  console.log(
185	    "Done. Postgres returns the freed space to each table's free list, not to the\n" +
186	      "filesystem — autovacuum reclaims it in the background, or run VACUUM by hand if\n" +
187	      "you need the disk back immediately.",
188	  );
189	}
190	
191	try {
192	  await main();
193	
194	  console.log("");
195	  console.log("Never pruned, by policy:");
196	  for (const item of NEVER_PRUNED) console.log(`  · ${item.target}`);
197	  console.log("  (see docs/retention.md for why)");
198	  console.log("");
199	} finally {
200	  await db.$disconnect();
201	}
