1	import nodemailer from "nodemailer";
2	import { db } from "@/lib/db";
3	import { isMailConfigured } from "@/lib/mail";
4	import { getBalance, averageBuildCredits } from "@/lib/credits";
5	import { billingEnabled } from "@/lib/stripe";
6	import { creditState } from "./credit-state";
7	import {
8	  buildFailedEmail,
9	  lowCreditsEmail,
10	  sitePublishedEmail,
11	  welcomeEmail,
12	  type Email,
13	  type EmailKind,
14	} from "./templates";
15	
16	// The notification dispatcher.
17	//
18	// Two hard rules, both enforced structurally rather than by convention:
19	//
20	//   1. EVERY SEND IS ADDRESSED FROM THE DATABASE. No function here takes an
21	//      email address. You pass a userId / buildId / projectId, and the
22	//      recipient is looked up from that row's owner. It is therefore not
23	//      possible to call anything in this file in a way that mails one person
24	//      another person's account state.
25	//   2. NOTHING HERE CAN FAIL A REQUEST. Every send* function catches its own
26	//      errors and returns a result; the notify* wrappers don't even return a
27	//      promise. A dead SMTP server must never fail a build, a publish or a
28	//      signup.
29	
30	// ── Transport ─────────────────────────────────────────────────────────────
31	//
32	// NOTE FOR THE OWNER OF lib/mail.ts — this is the one piece of duplication in
33	// this module and it should not survive. lib/mail.ts already builds and caches
34	// exactly this transporter, but keeps it module-private and exposes only
35	// sendContactEmail(), which always sends to CONTACT_TO. There is no exported
36	// way to send an arbitrary transactional message, and this module may not edit
37	// that file. So the transport below is deliberately built from THE SAME env
38	// vars, with the same secure/port logic and the same envelope sender, and the
39	// "is it configured" predicate is imported rather than re-implemented.
40	//
41	// The patch that deletes this block is ~6 lines in lib/mail.ts:
42	//
43	//   export async function sendMail(msg: nodemailer.SendMailOptions) {
44	//     await transporter().sendMail({ from: FROM, ...msg });
45	//   }
46	//
47	// Once that exists, import it here and delete `transport()` and `FROM`.
48	
49	const FROM = process.env.MAIL_FROM ?? "Kodely <noreply@kodely.me>";
50	const PORT = Number(process.env.SMTP_PORT ?? 587);
51	
52	let cached: nodemailer.Transporter | null = null;
53	
54	function transport(): nodemailer.Transporter {
55	  if (!cached) {
56	    cached = nodemailer.createTransport({
57	      host: process.env.SMTP_HOST,
58	      port: PORT,
59	      secure: PORT === 465,
60	      auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS },
61	      // The cron path sends in a loop; a hung SMTP connection must not wedge
62	      // the whole run. lib/mail.ts doesn't set these because its one caller is
63	      // a single interactive request.
64	      connectionTimeout: 10_000,
65	      greetingTimeout: 10_000,
66	      socketTimeout: 20_000,
67	    });
68	  }
69	  return cached;
70	}
71	
72	// ── Operational guards ────────────────────────────────────────────────────
73	
74	/** Master off switch. Set KODELY_NOTIFY_DISABLED=1 to stop all sending. */
75	function disabled(): boolean {
76	  return process.env.KODELY_NOTIFY_DISABLED === "1";
77	}
78	
79	/** Compose and log, never hand anything to SMTP. */
80	function dryRun(): boolean {
81	  return process.env.KODELY_NOTIFY_DRY_RUN === "1";
82	}
83	
84	/**
85	 * Rollout safety net. With KODELY_NOTIFY_ALLOWLIST set to a comma-separated
86	 * list of addresses, everyone else is skipped. Turn this on first, watch real
87	 * mail arrive at your own address, then remove it.
88	 */
89	function allowlist(): Set<string> | null {
90	  const raw = process.env.KODELY_NOTIFY_ALLOWLIST;
91	  if (!raw) return null;
92	  const entries = raw
93	    .split(",")
94	    .map((e) => e.trim().toLowerCase())
95	    .filter(Boolean);
96	  return entries.length > 0 ? new Set(entries) : null;
97	}
