82	export async function scanLowCredits(slot: Slot): Promise<LowCreditsDue[]> {
83	  // Every spend in the slot. Grants are irrelevant — a balance can only cross
84	  // downwards on a negative delta.
85	  const rows = await db.creditLedger.findMany({
86	    // userId is nullable: erasing an account DETACHES its ledger rows rather
87	    // than deleting them, so the financial record survives (see the comment on
88	    // CreditLedger in prisma/schema.prisma). A detached row belongs to nobody,
89	    // so there is nobody to email. Excluded in the query so the index does the
90	    // work rather than filtering in memory afterwards.
91	    where: {
92	      createdAt: { gte: slot.start, lt: slot.end },
93	      delta: { lt: 0 },
94	      userId: { not: null },
95	    },
96	    orderBy: { createdAt: "asc" },
97	    select: { id: true, userId: true, delta: true, balanceAfter: true, createdAt: true },
98	  });
99	
100	  // Only the last spend of the slot per user can be the crossing row.
101	  // The filter above is what makes this key safe; TypeScript cannot see
102	  // through a Prisma `where`, so narrow explicitly rather than asserting.
103	  const lastPerUser = new Map<string, (typeof rows)[number] & { userId: string }>();
104	  for (const row of rows) {
105	    if (row.userId === null) continue;
106	    lastPerUser.set(row.userId, { ...row, userId: row.userId });
107	  }
108	
109	  const due: LowCreditsDue[] = [];
110	
111	  for (const row of lastPerUser.values()) {
112	    // Anything newer than this row — another build, a top-up, a reward grant —
113	    // means this row is no longer the user's current state. Skipping is safe
114	    // and lossless: the newer row belongs to a later slot and gets its own
115	    // evaluation on a later run.
116	    const newer = await db.creditLedger.count({
117	      where: { userId: row.userId, createdAt: { gt: row.createdAt } },
118	    });
119	    if (newer > 0) continue;
120	
121	    // Both sides are graded with the SAME average — the one measured now.
