124	    const avg = await averageBuildCredits(row.userId);
125	    const after = creditState(row.balanceAfter, avg);
126	    // delta is negative, so this is the balance immediately before the spend.
127	    const before = creditState(row.balanceAfter - row.delta, avg);
128	
129	    // The transition, not the condition. Someone who was already in this grade
130	    // before the build has been told about it and is not told again.
131	    if (!droppedIntoWarning(before, after)) continue;
132	
133	    due.push({
134	      userId: row.userId,
135	      crossingLedgerId: row.id,
136	      balanceAfter: row.balanceAfter,
137	      avgBuildCredits: avg,
138	      buildsLeft: after.buildsLeft,
